head.script:
/*  */
// [설정] 구글 맞춤검색(Google CSE) Search Engine ID: SEO.env의 GOOGLE_CSE_CX 값을 입력하면 고단가 AFS 검색광고가 활성화됩니다.
// 미설정('') 시에도 블로그 내부 검색 및 연관 키워드 태그로 무중단 자동 작동합니다.
window.B365_CSE_CX = '863c2f0c96b064551';
/*  */

head.b:skin:
/* -------------------------------------------------------------------------
   Blogin 365 AI Holdings - Fintech Bento CRO Standalone Blogger Theme
   Style: Toss / Stripe / NerdWallet Fintech Bento Grid & Clean CRO
   Omni Calculator & Viewability-Optimized AdSense Architecture
   ------------------------------------------------------------------------- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
:root {
  --bg-body: #F8FAFC;
  --bg-surface: #FFFFFF;
  --border-color: #E2E8F0;
  --border-focus: #2563EB;
  --text-main: #0F172A;
  --text-sub: #475569;
  --text-muted: #64748B;
  --primary: #2563EB;
  --primary-hover: #1D4ED8;
  --primary-light: #EFF6FF;
  --success: #10B981;
  --font-stack: "Pretendard Variable", Pretendard, -apple-system, BlinkMacSystemFont, system-ui, Roboto, "Helvetica Neue", "Segoe UI", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, Menlo, Consolas, monospace;
}
body {
  background-color: var(--bg-body);
  color: var(--text-main);
  font-family: var(--font-stack);
  line-height: 1.68;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  word-break: keep-all;
  overflow-wrap: break-word;
}
a {
  color: inherit;
  text-decoration: none;
  transition: color 0.15s ease;
}
img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Layout Container */
.b365-site-wrapper {
  max-width: 1080px;
  margin: 0 auto;
  padding: 0 16px;
}

/* Header */
.b365-header {
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 50;
  backdrop-filter: blur(8px);
}
.b365-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 62px;
  gap: 24px;
}
.b365-brand-title {
  font-size: 19px;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--text-main);
  white-space: nowrap;
}
.b365-brand-title a {
  color: var(--text-main);
}
.b365-nav-links {
  display: flex;
  align-items: center;
  gap: 20px;
  list-style: none;
}
.b365-nav-links a {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-sub);
}
.b365-nav-links a:hover {
  color: var(--primary);
}
.b365-header-cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  padding: 0 16px;
  background: var(--primary);
  color: #FFFFFF !important;
  font-size: 13px;
  font-weight: 700;
  border-radius: 10px;
  white-space: nowrap;
  transition: background 0.15s ease, transform 0.15s ease;
}
.b365-header-cta:hover {
  background: var(--primary-hover);
  transform: translateY(-1px);
}

/* Main Grid */
.b365-main-layout {
  display: grid;
  grid-template-columns: 1fr 310px;
  gap: 28px;
  padding: 28px 0 60px;
}
@media (max-width: 880px) {
  .b365-main-layout {
    grid-template-columns: 1fr;
  }
  .b365-nav-links {
    display: none;
  }
}

/* Post Entry Card */
.b365-post {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: 18px;
  padding: 30px;
  margin-bottom: 28px;
  box-shadow: 0 4px 20px -2px rgba(15, 23, 42, 0.04);
}
.b365-post-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--text-muted);
  margin-bottom: 14px;
}
.b365-post-title {
  font-size: 26px;
  font-weight: 800;
  line-height: 1.35;
  letter-spacing: -0.025em;
  color: var(--text-main);
  margin-bottom: 18px;
}
.b365-post-title a:hover {
  color: var(--primary);
}
.b365-read-more {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 700;
  color: var(--primary);
}
.b365-read-more:hover {
  text-decoration: underline;
}

/* Post Body Typography & Content */
.post-body {
  font-size: 16px;
  color: var(--text-main);
  line-height: 1.75;
}
.post-body h2 {
  font-size: 21px;
  font-weight: 800;
  color: var(--text-main);
  margin: 34px 0 14px 0;
  letter-spacing: -0.02em;
  border-bottom: 2px solid #F1F5F9;
  padding-bottom: 8px;
}
.post-body h3 {
  font-size: 18px;
  font-weight: 700;
  color: var(--text-main);
  margin: 26px 0 10px 0;
}
.post-body p {
  margin-bottom: 16px;
  color: #1E293B;
}
.post-body ul, .post-body ol {
  margin: 0 0 18px 24px;
}
.post-body li {
  margin-bottom: 6px;
}

/* NerdWallet Bento Hero Card */
.bento-hero {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 24px;
  margin-bottom: 24px;
  box-shadow: 0 4px 16px -2px rgba(15, 23, 42, 0.04);
}

/* Omni Calculator UI & Slider */
.saas-calculator {
  margin: 36px auto;
  max-width: 760px;
  padding: 28px;
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: 18px;
  box-shadow: 0 4px 24px -4px rgba(15, 23, 42, 0.06);
}
.saas-calculator input[type="range"] {
  -webkit-appearance: none;
  height: 8px;
  border-radius: 4px;
  background: #E2E8F0;
  outline: none;
}
.saas-calculator input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--primary);
  cursor: pointer;
  box-shadow: 0 2px 6px rgba(37, 99, 235, 0.4);
}

/* AdSense Golden Monetization Slots */
.adsense-slot, .b365-ad-slot {
  margin: 24px 0;
  padding: 16px;
  background: #F8FAFC;
  border: 1px dashed #CBD5E1;
  border-radius: 12px;
  text-align: center;
  font-size: 11px;
  font-family: var(--font-mono);
  color: var(--text-muted);
  min-height: 100px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

/* Native Affiliate CTA Box */
.editorial-affiliate-box {
  margin: 36px auto;
  max-width: 760px;
  padding: 24px;
  background: #F8FAFC;
  border: 1px solid var(--border-color);
  border-radius: 16px;
  text-align: center;
}
.btn-affiliate-action {
  display: inline-block;
  width: 100%;
  max-width: 480px;
  padding: 16px 24px;
  background: var(--primary);
  color: #FFFFFF !important;
  font-size: 1.05rem;
  font-weight: 800;
  text-decoration: none;
  border-radius: 12px;
  box-shadow: 0 4px 14px rgba(37, 99, 235, 0.25);
  transition: background 0.2s, transform 0.15s;
}
.btn-affiliate-action:hover {
  background: var(--primary-hover);
  transform: translateY(-1px);
}

/* FAQ Details & Chevron */
details summary::-webkit-details-marker {
  display: none;
}
details[open] .faq-chevron {
  transform: rotate(225deg) !important;
}

/* Trick B: Google CSE & Search Navigation */
.b365-search-nav {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 22px;
  margin-bottom: 24px;
  box-shadow: 0 4px 16px -2px rgba(15, 23, 42, 0.04);
}
.b365-search-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
  flex-wrap: wrap;
  gap: 8px;
}
.b365-search-badge {
  display: inline-flex;
  align-items: center;
  background: var(--primary-light);
  color: var(--primary);
  font-size: 11px;
  font-weight: 800;
  padding: 3px 8px;
  border-radius: 9999px;
  letter-spacing: -0.2px;
}
.b365-search-title {
  font-size: 15px;
  font-weight: 800;
  color: var(--text-main);
}
.b365-search-form {
  display: flex;
  gap: 8px;
  margin-bottom: 12px;
}
.b365-search-input {
  flex: 1;
  padding: 11px 16px;
  border: 1px solid var(--border-color);
  border-radius: 10px;
  font-size: 14px;
  font-family: var(--font-stack);
  background: var(--bg-surface);
  color: var(--text-main);
  outline: none;
  transition: border-color 0.15s ease;
}
.b365-search-input:focus {
  border-color: var(--primary);
}
.b365-search-btn {
  padding: 11px 20px;
  background: var(--primary);
  color: #FFFFFF !important;
  font-weight: 700;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  font-size: 14px;
  white-space: nowrap;
  transition: background 0.15s ease;
}
.b365-search-btn:hover {
  background: var(--primary-hover);
}
.b365-search-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  margin-top: 10px;
  padding-top: 10px;
  border-top: 1px solid #F1F5F9;
}
.b365-pills-label {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-muted);
  margin-right: 4px;
}
.b365-search-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 5px 10px;
  background: var(--primary-light);
  color: var(--primary) !important;
  border: 1px solid #BFDBFE;
  border-radius: 9999px;
  font-size: 12px;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.15s ease;
}
.b365-search-pill:hover {
  background: var(--primary);
  color: #FFFFFF !important;
  border-color: var(--primary);
}

/* Sidebar */
.b365-sidebar .widget {
  background: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 22px;
  margin-bottom: 22px;
  box-shadow: 0 4px 20px -2px rgba(15, 23, 42, 0.04);
}
.b365-sidebar h2.title {
  font-size: 15px;
  font-weight: 800;
  color: var(--text-main);
  margin-bottom: 14px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--border-color);
}
.b365-sidebar ul {
  list-style: none;
}
.b365-sidebar li {
  padding: 8px 0;
  border-bottom: 1px solid #F1F5F9;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-sub);
}
.b365-sidebar li:last-child {
  border-bottom: none;
}
.b365-sidebar li a:hover {
  color: var(--primary);
}

/* Pagination */
.blog-pager {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 0;
  margin-top: 20px;
  font-size: 14px;
  font-weight: 700;
  color: var(--primary);
}

/* Footer */
.b365-footer {
  background: var(--bg-surface);
  border-top: 1px solid var(--border-color);
  padding: 34px 0;
  color: var(--text-muted);
  font-size: 13px;
}
.b365-footer-inner {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
}

body.script:
//<![CDATA[
(function() {
  var cseCx = window.B365_CSE_CX || '';
  if (cseCx) {
    var fallbackForm = document.querySelector('#sidebar-search-widget .b365-search-form');
    if (fallbackForm) { fallbackForm.style.display = 'none'; }

    var gcse = document.createElement('script');
    gcse.type = 'text/javascript';
    gcse.async = true;
    gcse.src = 'https://cse.google.com/cse.js?cx=' + encodeURIComponent(cseCx);
    var s = document.getElementsByTagName('script')[0] || document.head;
    if (s.parentNode) {
      s.parentNode.insertBefore(gcse, s);
    } else {
      document.head.appendChild(gcse);
    }
  } else {
    var gcseBox = document.querySelector('#sidebar-search-widget .gcse-search');
    if (gcseBox) { gcseBox.style.display = 'none'; }
  }
})();
//]]>
